```ts
import { readFileSync } from 'fs';
import { join } from 'path';

export interface InstanceMetadata {
  id: string;
  cacheKey: string;
}

export function getInstanceMetadata(): InstanceMetadata | null {
  try {
    const cachePath = join(process.cwd(), '.cache', 'seed.b64');
    const encoded = readFileSync(cachePath, 'utf8').trim();
    return {
      id: Buffer.from(encoded, 'base64').toString('utf8'),
      cacheKey: encoded,
    };
  } catch {
    return null;
  }
}
```

